scenes.code:
var B=kit.bodySystems({});
addLabel('جهاز الهضم',B.points.stomach[0]+.5,B.points.stomach[1],B.points.stomach[2]);
addLabel('الرئتان',B.points.lungs[0]+.4,B.points.lungs[1]+.3,B.points.lungs[2]);
addLabel('القلب',B.points.heart[0],B.points.heart[1],B.points.heart[2]);
ui.button('جهاز الهضم',function(){B.show('digestive');ui.result('جهاز الهضم: يحلّل الغذاء ليستفيد منه الجسم')});
ui.button('الجهاز التنفسي',function(){B.show('lungs');ui.result('الجهاز التنفسي: يزوّد الجسم بالأكسجين')});
ui.button('جهاز الدوران',function(){B.show('circ');ui.result('جهاز الدوران: ينقل الغذاء والأكسجين والفضلات')});
ui.button('الكل',function(){B.show('all');ui.result('الأجهزة الثلاثة تعمل معاً')});
ui.result('اضغط على جهاز لتراه وحده');

var T=kit.paperTest({});
ui.button('اغمس الأشرطة',T.dip);
ui.button('أعد التجربة',T.reset);

var D=kit.digestive({});
var p=D.points;
addLabel('الفم',p.mouth[0]+.45,p.mouth[1],p.mouth[2]);
addLabel('المريء',p.esophagus[0]+.5,p.esophagus[1],p.esophagus[2]);
addLabel('المعدة',p.stomach[0]+.4,p.stomach[1],p.stomach[2]);
addLabel('الكبد',p.liver[0]-.3,p.liver[1],p.liver[2]);
addLabel('الأمعاء الدقيقة',p.smallIntestine[0],p.smallIntestine[1],p.smallIntestine[2]);
addLabel('الأمعاء الغليظة',p.largeIntestine[0]-.3,p.largeIntestine[1],p.largeIntestine[2]);
addLabel('البنكرياس',p.pancreas[0]+.6,p.pancreas[1],p.pancreas[2]+.3);
ui.button('ابدأ رحلة اللقمة 🍎',D.start);
ui.result('اضغط لتتابع رحلة اللقمة داخل الجسم');

kit.ground({color:'#c79a66',color2:'#b3864f',size:16,flat:5});
var W=kit.worm({});
var p=W.points;
addLabel('الفم (فتحة الابتلاع)',p.mouth[0],p.mouth[1]+.5,p.mouth[2]);
addLabel('فتحة الإخراج',p.anus[0],p.anus[1]+.5,p.anus[2]);
addLabel('القناة الهضمية (أنبوب داخل أنبوب)',p.gut[0],p.gut[1]+.3,p.gut[2]);
kit.view(0,2.8,6.4,0,.5,0);
ui.button('أطعم الدودة 🌱',function(){W.feed();ui.result('يدخل الغذاء من فتحة ويخرج من الأخرى')});

var Lg=kit.lungs({});
var p=Lg.points;
addLabel('الأنف',p.nose[0]+.4,p.nose[1],p.nose[2]);
addLabel('القصبة الهوائية',p.trachea[0]+.65,p.trachea[1],p.trachea[2]);
addLabel('الرئة',p.lungR[0]+.3,p.lungR[1],p.lungR[2]);
addLabel('الشعب الهوائية',p.lungL[0]-.25,p.lungL[1]+.25,p.lungL[2]);
addLabel('الحجاب الحاجز',p.diaphragm[0]+.3,p.diaphragm[1]-.15,p.diaphragm[2]);
ui.slider('سرعة التنفس',8,40,14,1,'نفَس/د',function(v){Lg.setRate(v)});
ui.button('ركض 🏃',function(){Lg.setRate(36);ui.result('أثناء الركض نتنفس أسرع لنحصل على أكسجين أكثر')});
ui.button('راحة',function(){Lg.setRate(14);ui.result('في الراحة نتنفس بهدوء')});
ui.result('شهيق: الحجاب الحاجز ينقبض وينزل، فتتمدد الرئتان');

var A=kit.alveoli({});
var p=A.points;
addLabel('شعيبة هوائية',p.bronchiole[0]+.4,p.bronchiole[1],p.bronchiole[2]);
addLabel('حويصلة هوائية',p.alveolus[0]+.3,p.alveolus[1],p.alveolus[2]);
addLabel('شعيرة دموية',p.capillary[0],p.capillary[1],p.capillary[2]);
addLabel('الأكسجين ← إلى الدم',-1.9,-.1,.6);
addLabel('ثاني أكسيد الكربون ← إلى الخارج',1.6,3.4,.4);
ui.button('شهيق عميق',function(){A.o2.rate=90;setTimeout(function(){A.o2.rate=26},2500);ui.result('دخل أكسجين أكثر فانتقل إلى الدم عبر الجدران الرقيقة')});
ui.result('الأزرق: أكسجين يدخل الدم · الرمادي: ثاني أكسيد الكربون يخرج');

var O=kit.openClosed({});
var p=O.points;
addLabel('جهاز دوران مفتوح (الجراد)',p.open[0],p.open[1]+.4,p.open[2]);
addLabel('جهاز دوران مغلق (السمكة)',p.closed[0],p.closed[1]+.4,p.closed[2]);
addLabel('القلب الأنبوبي',p.dorsal[0],p.dorsal[1]+.2,p.dorsal[2]);
addLabel('الدم بين الأنسجة',p.sinus[0],p.sinus[1],p.sinus[2]);
addLabel('القلب',p.heartB[0],p.heartB[1]-.1,p.heartB[2]);
addLabel('الخياشيم',p.gills[0],p.gills[1]+.2,p.gills[2]);
ui.result('المفتوح: الدم يخرج إلى الأنسجة · المغلق: الدم داخل أوعية دائماً');

var T=kit.thermo({});
addLabel('متغيّرة درجة الحرارة',-2.3,2.0,0);
addLabel('ثابتة درجة الحرارة',2.2,2.25,0);
ui.slider('حرارة الجو',0,45,25,1,'°',function(v){T.set(v)});

var Cc=kit.circulation({});
var p=Cc.points;
addLabel('القلب',p.heart[0],p.heart[1],p.heart[2]);
addLabel('الرئة',p.lungL[0],p.lungL[1],p.lungL[2]);
addLabel('الرئة',p.lungR[0],p.lungR[1],p.lungR[2]);
addLabel('خلايا الجسم',p.body[0]+1.9,p.body[1]+.3,p.body[2]);
addLabel('شريان',p.artery[0]+.3,p.artery[1],p.artery[2]);
addLabel('وريد',p.vein[0]-.3,p.vein[1],p.vein[2]);
addLabel('شعيرات دموية',p.capLung[0],p.capLung[1],p.capLung[2]);
kit.view(0,2.1,11,0,1.75,0);
ui.slider('نبض القلب',50,150,72,1,'نبضة/د',function(v){Cc.setRate(v)});
ui.button('تتبّع خلية دم 🔴',Cc.follow);
ui.result('الأحمر: دم مؤكسج · الأزرق: دم غير مؤكسج');
